import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#define BLOCK_THREADS 256
// Optimization: the previous single cooperative launch capped the grid
// at the number of co-resident blocks (very few per SM here because of
// the double-precision accumulators and float4 registers) and paid for
// three grid-wide grid.sync() barriers, so all three phases ran on a
// small, occupancy-limited grid and the elementwise normalize pass was
// serialized into a per-thread loop over every row. This version drops
// cooperative groups entirely and uses three lightweight back-to-back
// kernels (stats / finalize / normalize) launched on plain grids sized
// to fill the whole GPU: every phase runs at full occupancy with no
// cooperative-launch restriction and no grid.sync serialization, and
// the normalize pass maps one float4 per thread across the entire
// tensor for perfectly coalesced, fully parallel elementwise access.
// Pass 1: split-row partial reduction. One block per (row, split) chunk;
// each block block-reduces its chunk in shared memory and atomically
// accumulates the (sum, sum of squares) pair for its row.
__global__ void layernorm_stats_kernel(const float4* __restrict__ x,
                                       double* __restrict__ stats,
                                       int nv, long rows, int splits) {
    const long chunk = ((long)nv + splits - 1) / splits;
    const long c     = blockIdx.x;
    const long row   = c / splits;
    const long split = c - row * splits;
    long begin = split * chunk;
    long end   = begin + chunk;
    if (end > (long)nv) end = (long)nv;
    const float4* xr = x + row * (long)nv;
    double s = 0.0, sq = 0.0;
    for (long i = begin + threadIdx.x; i < end; i += BLOCK_THREADS) {
        float4 v = __ldg(xr + i);
        s  += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sq += (double)v.x * v.x + (double)v.y * v.y +
              (double)v.z * v.z + (double)v.w * v.w;
    }
    const unsigned full_mask = 0xffffffffu;
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    __shared__ double ss[BLOCK_THREADS / 32];
    __shared__ double ssq[BLOCK_THREADS / 32];
    for (int offset = 16; offset > 0; offset >>= 1) {
        s  += __shfl_down_sync(full_mask, s, offset);
        sq += __shfl_down_sync(full_mask, sq, offset);
    }
    if (lane == 0) {
        ss[warp]  = s;
        ssq[warp] = sq;
    }
    __syncthreads();
    if (warp == 0) {
        s  = (lane < (BLOCK_THREADS / 32)) ? ss[lane]  : 0.0;
        sq = (lane < (BLOCK_THREADS / 32)) ? ssq[lane] : 0.0;
        for (int offset = (BLOCK_THREADS / 32) / 2; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(full_mask, s, offset);
            sq += __shfl_down_sync(full_mask, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(stats + row * 2,     s);
            atomicAdd(stats + row * 2 + 1, sq);
        }
    }
}
// Pass 2: tiny per-row finalize, turning (sum, sum of squares) into
// (mean, rstd) in place.
__global__ void layernorm_finalize_kernel(double* __restrict__ stats,
                                          long rows, long n, float eps) {
    const long stride = (long)gridDim.x * blockDim.x;
    for (long row = (long)blockIdx.x * blockDim.x + threadIdx.x;
         row < rows; row += stride) {
        double sum  = stats[row * 2];
        double sumq = stats[row * 2 + 1];
        double mean = sum / (double)n;
        double var  = sumq / (double)n - mean * mean;
        stats[row * 2]     = mean;
        stats[row * 2 + 1] = rsqrt(var + (double)eps);
    }
}
// Pass 3: fully parallel normalize. One float4 per thread with a grid
// that covers the whole tensor, so the elementwise pass runs at full
// occupancy with coalesced loads/stores instead of being limited to
// the co-resident cooperative grid.
__global__ void layernorm_normalize_kernel(const float4* __restrict__ x,
                                           const float4* __restrict__ w,
                                           const float4* __restrict__ b,
                                           float4* __restrict__ y,
                                           const double* __restrict__ stats,
                                           long total, int nv) {
    long idx = (long)blockIdx.x * BLOCK_THREADS + threadIdx.x;
    if (idx >= total) return;
    long row = idx / (long)nv;
    long i   = idx - row * (long)nv;
    double mean = __ldg(stats + row * 2);
    double rstd = __ldg(stats + row * 2 + 1);
    float4 v  = __ldg(x + idx);
    float4 wv = __ldg(w + i);
    float4 bv = __ldg(b + i);
    float4 o;
    o.x = (float)(((double)v.x - mean) * rstd) * wv.x + bv.x;
    o.y = (float)(((double)v.y - mean) * rstd) * wv.y + bv.y;
    o.z = (float)(((double)v.z - mean) * rstd) * wv.z + bv.z;
    o.w = (float)(((double)v.w - mean) * rstd) * wv.w + bv.w;
    y[idx] = o;
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w,
                                torch::Tensor b, double eps) {
    TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32,
                "input must be a CUDA float tensor");
    auto xc = x.contiguous();
    auto wc = w.contiguous();
    auto bc = b.contiguous();
    auto y  = torch::empty_like(xc);
    long n    = wc.numel();
    long rows = xc.numel() / n;
    TORCH_CHECK(n % 4 == 0, "normalized size must be divisible by 4");
    int nv = (int)(n / 4);
    const float4* xp = reinterpret_cast<const float4*>(xc.data_ptr<float>());
    const float4* wp = reinterpret_cast<const float4*>(wc.data_ptr<float>());
    const float4* bp = reinterpret_cast<const float4*>(bc.data_ptr<float>());
    float4* yp       = reinterpret_cast<float4*>(y.data_ptr<float>());
    float epsf       = (float)eps;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    // Per-row scratch: starts as (sum, sum of squares), overwritten in
    // place with (mean, rstd) by the finalize kernel.
    auto stats = torch::empty({rows, 2},
                 torch::TensorOptions().dtype(torch::kFloat64).device(xc.device()));
    double* sp = stats.data_ptr<double>();
    int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    // Zero the tiny stats accumulator before the atomic split-row
    // reduction (a few hundred bytes, fully asynchronous).
    cudaMemsetAsync(sp, 0, rows * 2 * sizeof(double), stream);
    // Split each row so rows*splits blocks fill the GPU several times
    // over; every block handles one contiguous chunk of a row.
    long target = (long)sms * 8;
    long splits = (target + rows - 1) / (rows > 0 ? rows : 1);
    if (splits < 1)  splits = 1;
    if (splits > 64) splits = 64;
    long min_chunk  = (long)BLOCK_THREADS * 4;
    long max_splits = ((long)nv + min_chunk - 1) / min_chunk;
    if (max_splits < 1) max_splits = 1;
    if (splits > max_splits) splits = max_splits;
    int splits_i = (int)splits;
    long sblocks = rows * splits;
    if (sblocks < 1) sblocks = 1;
    layernorm_stats_kernel<<<dim3((unsigned)sblocks), dim3(BLOCK_THREADS), 0, stream>>>(
        xp, sp, nv, rows, splits_i);
    long fblocks = (rows + BLOCK_THREADS - 1) / BLOCK_THREADS;
    if (fblocks > 1024) fblocks = 1024;
    if (fblocks < 1) fblocks = 1;
    layernorm_finalize_kernel<<<dim3((unsigned)fblocks), dim3(BLOCK_THREADS), 0, stream>>>(
        sp, rows, n, epsf);
    long total = rows * (long)nv;
    long nblocks = (total + BLOCK_THREADS - 1) / BLOCK_THREADS;
    if (nblocks < 1) nblocks = 1;
    layernorm_normalize_kernel<<<dim3((unsigned)nblocks), dim3(BLOCK_THREADS), 0, stream>>>(
        xp, wp, bp, yp, sp, total, nv);
    return y;
}
"""

cpp_src = ("torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w, "
           "torch::Tensor b, double eps);")

_mod = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    verbose=False,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.layernorm_forward(x, self.weight, self.bias, self.eps)

