#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>

namespace cg = cooperative_groups;

#define BLOCK_THREADS 256

// Fused single-launch LayerNorm built around cooperative groups.
// Optimization: kernel fusion via grid-wide synchronization. The previous
// design used three kernels (stats / finalize / normalize), so the input
// tensor x was read from global memory twice and each call paid for three
// kernel launches plus a zero-init memset of the stats buffer. This fused
// kernel performs all phases in one cooperative launch separated by
// grid.sync(): the stats phase keeps its per-block partial sums in
// registers, so x is read from global memory only once, and the tiny
// stats buffer is zeroed and finalized in-kernel.
__global__ void layernorm_fused_kernel(const float4* __restrict__ x,
                                       const float4* __restrict__ w,
                                       const float4* __restrict__ b,
                                       float4* __restrict__ y,
                                       double* __restrict__ stats,
                                       int nv, long rows, long n,
                                       float eps, int splits) {
    cg::grid_group grid = cg::this_grid();
    const long gstride = (long)gridDim.x * BLOCK_THREADS;
    const long gtid    = (long)blockIdx.x * BLOCK_THREADS + threadIdx.x;
    const unsigned full_mask = 0xffffffffu;
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    __shared__ double ss[BLOCK_THREADS / 32];
    __shared__ double ssq[BLOCK_THREADS / 32];
    // Phase 0: zero the per-row (sum, sum of squares) stats buffer.
    for (long i = gtid; i < rows * 2; i += gstride) {
        stats[i] = 0.0;
    }
    grid.sync();
    // Phase 1: split-row reduction. Each block grabs (row, split) chunks
    // grid-stride style and atomically accumulates its partial sums.
    const long chunk = ((long)nv + splits - 1) / splits;
    const long total_chunks = rows * (long)splits;
    for (long c = blockIdx.x; c < total_chunks; c += gridDim.x) {
        long row   = c / splits;
        long split = c % splits;
        long begin = split * chunk;
        long end   = begin + chunk;
        if (end > (long)nv) end = (long)nv;
        const float4* xr = x + row * (long)nv;
        double s = 0.0, sq = 0.0;
        for (long i = begin + threadIdx.x; i < end; i += BLOCK_THREADS) {
            float4 v = __ldg(xr + i);
            s  += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
            sq += (double)v.x * v.x + (double)v.y * v.y +
                  (double)v.z * v.z + (double)v.w * v.w;
        }
        for (int offset = 16; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(full_mask, s, offset);
            sq += __shfl_down_sync(full_mask, sq, offset);
        }
        if (lane == 0) {
            ss[warp]  = s;
            ssq[warp] = sq;
        }
        __syncthreads();
        if (warp == 0) {
            s  = (lane < (BLOCK_THREADS / 32)) ? ss[lane]  : 0.0;
            sq = (lane < (BLOCK_THREADS / 32)) ? ssq[lane] : 0.0;
            for (int offset = (BLOCK_THREADS / 32) / 2; offset > 0; offset >>= 1) {
                s  += __shfl_down_sync(full_mask, s, offset);
                sq += __shfl_down_sync(full_mask, sq, offset);
            }
            if (lane == 0) {
                atomicAdd(stats + row * 2,     s);
                atomicAdd(stats + row * 2 + 1, sq);
            }
        }
        __syncthreads();
    }
    grid.sync();
    // Phase 2: derive per-row (mean, rstd) once, overwriting the raw sums.
    for (long row = gtid; row < rows; row += gstride) {
        double sum  = stats[row * 2];
        double sumq = stats[row * 2 + 1];
        double mean = sum / (double)n;
        double var  = sumq / (double)n - mean * mean;
        stats[row * 2]     = mean;
        stats[row * 2 + 1] = rsqrt(var + (double)eps);
    }
    grid.sync();
    // Phase 3: fully parallel normalize. Each block owns a column slice and
    // reuses that weight/bias slice across all rows in registers.
    for (long i = gtid; i < (long)nv; i += gstride) {
        float4 wv = __ldg(w + i);
        float4 bv = __ldg(b + i);
        for (long row = 0; row < rows; ++row) {
            double mean = __ldg(stats + row * 2);
            double rstd = __ldg(stats + row * 2 + 1);
            long off = row * (long)nv + i;
            float4 v = __ldcs(x + off);
            float4 o;
            o.x = (float)(((double)v.x - mean) * rstd) * wv.x + bv.x;
            o.y = (float)(((double)v.y - mean) * rstd) * wv.y + bv.y;
            o.z = (float)(((double)v.z - mean) * rstd) * wv.z + bv.z;
            o.w = (float)(((double)v.w - mean) * rstd) * wv.w + bv.w;
            __stcs(y + off, o);
        }
    }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor w,
                                torch::Tensor b, double eps) {
    TORCH_CHECK(x.is_cuda() && x.scalar_type() == torch::kFloat32,
                "input must be a CUDA float tensor");
    auto xc = x.contiguous();
    auto wc = w.contiguous();
    auto bc = b.contiguous();
    auto y  = torch::empty_like(xc);
    long n    = wc.numel();
    long rows = xc.numel() / n;
    TORCH_CHECK(n % 4 == 0, "normalized size must be divisible by 4");
    int nv = (int)(n / 4);
    const float4* xp = reinterpret_cast<const float4*>(xc.data_ptr<float>());
    const float4* wp = reinterpret_cast<const float4*>(wc.data_ptr<float>());
    const float4* bp = reinterpret_cast<const float4*>(bc.data_ptr<float>());
    float4* yp       = reinterpret_cast<float4*>(y.data_ptr<float>());
    float epsf       = (float)eps;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    // Per-row scratch: starts as (sum, sum of squares), later overwritten
    // in place with (mean, rstd) by the fused kernel. Zero-initialization
    // is done inside the kernel, so no separate memset launch is needed.
    auto stats = torch::empty({rows, 2},
                 torch::TensorOptions().dtype(torch::kFloat64).device(xc.device()));
    double* sp = stats.data_ptr<double>();
    // Size the grid to the number of co-resident blocks so the cooperative
    // launch is valid while still filling the whole GPU.
    int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    int blocks_per_sm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, (const void*)layernorm_fused_kernel, BLOCK_THREADS, 0);
    if (blocks_per_sm < 1) blocks_per_sm = 1;
    long nblocks = (long)sms * blocks_per_sm;
    if (nblocks < 1) nblocks = 1;
    // Split each row so that rows*splits chunks cover the resident blocks.
    long splits = (nblocks + rows - 1) / (rows > 0 ? rows : 1);
    if (splits < 1)  splits = 1;
    if (splits > 64) splits = 64;
    long min_chunk  = (long)BLOCK_THREADS * 4;
    long max_splits = ((long)nv + min_chunk - 1) / min_chunk;
    if (max_splits < 1) max_splits = 1;
    if (splits > max_splits) splits = max_splits;
    int splits_i = (int)splits;
    void* args[] = {(void*)&xp, (void*)&wp, (void*)&bp, (void*)&yp,
                    (void*)&sp, (void*)&nv, (void*)&rows, (void*)&n,
                    (void*)&epsf, (void*)&splits_i};
    cudaLaunchCooperativeKernel((const void*)layernorm_fused_kernel,
                                dim3((unsigned)nblocks), dim3(BLOCK_THREADS),
                                args, 0, stream);
    return y;
}
